import SwiftUI
import XCTest
@testable import Bain_Luck

/// #10868 — the hockey journey adapter, part one (phase, header, paired
/// matrix), on REAL served `/api/events/{id}` bodies decoded by `EventDetail`
/// exactly as the app decodes them (`.convertFromSnakeCase`).
///
/// RETAINED payloads, verbatim (sha256 in `cli-candidate-20261030/retained-payloads/MANIFEST.json`
/// and `atlas-v6/raw/manifest.json` under the event-page design directory):
/// - `wildBruinsFinal` — 15169793, Minnesota Wild 4–1 Boston Bruins, completed;
///   captured 2026-10-11T04:56:41Z (`atlas-v6/raw/nhl-15169793-detail.json`,
///   sha256 a11c662d…a348). The same game the accepted screen's prepared
///   cases are built from; its hero is the settled 1.0 / 0.0.
/// - `islandersWildFinal` — 15338034, New York Islanders 4–3 Minnesota Wild
///   (Final/OT), completed; captured 2026-10-30T20:13:55Z.
/// - `devilsKnightsBefore` — 15338496, New Jersey Devils at Vegas Golden
///   Knights, scheduled for 22:00Z; captured 2026-10-30T20:13:55Z, hero pair
///   0.505 / 0.495 observed 20:13:34Z, sportsbook projection 3.5 / 2.5 goals
///   (refused for hockey by the projected-final format table).
///
/// CONSTRUCTED here: the reader's calendar (Pacific, en_US) and the host's
/// clocks — `now` is the capture instant unless a test moves it, and the
/// displayed clock is the payload's own `hero_probability_observed_at`. No
/// payload field is edited. Expected clock words come from the adapter's own
/// date style so the assertions do not depend on the OS's spacing glyphs.
@MainActor
final class HockeyJourneyPageAdapter10868Tests: XCTestCase {
    private typealias A = HockeyJourneyPageAdapter10868

    private static let pacific: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "America/Los_Angeles")!
        return calendar
    }()

    private func host(observedAt: String?, now: String, interrupted: Bool = false) -> A.Host {
        A.Host(probabilityObservedAt: observedAt?.asDate, deliveryInterrupted: interrupted,
               now: now.asDate!, calendar: Self.pacific, locale: Locale(identifier: "en_US"))
    }

    private func detail(_ json: String) throws -> EventDetail {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(EventDetail.self, from: Data(json.utf8))
    }

    private func texts(_ matrix: HockeyJourneyMatrix10868) -> [String] {
        switch matrix {
        case .before(let m):
            return [m.home.chance, m.home.projectedGoals, m.away.chance, m.away.projectedGoals].map(\.text)
        case .during(let m):
            return [m.home.pregameChance, m.home.currentChance, m.home.goals, m.home.projectedFinal,
                    m.away.pregameChance, m.away.currentChance, m.away.goals, m.away.projectedFinal].map(\.text)
        case .final(let m):
            return [m.home.pregameChance, m.home.finalGoals, m.home.pregameForecast,
                    m.away.pregameChance, m.away.finalGoals, m.away.pregameForecast].map(\.text)
        }
    }

    // MARK: Final

    func testAFinishedGameRemembersThePregameChanceBesideTheFinalGoalsAndNeverPrintsTheSettledHero() throws {
        let event = try detail(Self.wildBruinsFinal)
        let host = host(observedAt: nil, now: "2026-10-11T04:56:41Z")
        XCTAssertEqual(A.phase(event, now: host.now), .final)
        XCTAssertEqual(A.header(event, phase: .final).title, "Final: Minnesota Wild 4–1 Boston Bruins")

        let headline = A.headline(event, host: host)
        XCTAssertEqual(headline.state, "Final")
        XCTAssertNil(headline.historicalForecast, "a pregame forecast during play is read during play only")
        guard case .final(let m) = headline.matrix else { return XCTFail("a final matrix") }
        // Served pre-match 0.66 / 0.34 with its own rendered percents, named by its caption word only:
        // `kalshi` is not among this payload's served source names, so it stays unnamed.
        XCTAssertEqual(m.home.pregameChance, .value("66%", spoken: "66 percent"))
        XCTAssertEqual(m.away.pregameChance, .value("34%", spoken: "34 percent"))
        XCTAssertEqual(m.pregameChance.provenance, "Pre-match")
        XCTAssertEqual(m.home.finalGoals, .value("4", spoken: "4 goals"))
        XCTAssertEqual(m.away.finalGoals, .value("1", spoken: "1 goal"))
        XCTAssertEqual(m.finalGoals.provenance,
                       "ESPN · score observed \(A.clockWords(try XCTUnwrap(event.scoreObservedAt?.asDate), host: host))")
        XCTAssertEqual(m.home.result, "Won")
        XCTAssertEqual(m.away.result, "Lost")
        // The hero is the settlement (hero_probability 1.0, source "settled"); no slot may show it as a chance.
        XCTAssertEqual(event.heroProbability, 1.0)
        for text in texts(headline.matrix) {
            XCTAssertFalse([">99%", "<1%", "100%", "0%"].contains(text), text)
        }
    }

    func testHockeyHasNoAdmittedFinalForecastSoThatColumnSaysSoInsteadOfAReferenceFigure() throws {
        for json in [Self.wildBruinsFinal, Self.islandersWildFinal] {
            let event = try detail(json)
            // #11296's unit table declines hockey, and the producer served no pregame_projection.
            XCTAssertNil(event.pregameProjection)
            XCTAssertNil(FinalForecastComparison11296.unit(forSport: event.sport))
            guard case .final(let m) = A.headline(event, host: host(observedAt: nil, now: "2026-10-30T20:13:55Z")).matrix
            else { return XCTFail("a final matrix") }
            XCTAssertEqual(m.home.pregameForecast, .absent("No pregame forecast"))
            XCTAssertEqual(m.away.pregameForecast, .absent("No pregame forecast"))
            XCTAssertNil(m.pregameForecast.provenance)
            XCTAssertNil(m.home.difference)
            XCTAssertNil(m.away.difference)
        }
    }

    func testAnOvertimeWinForTheAwayTeamIsReadFromTheServedVerdict() throws {
        let event = try detail(Self.islandersWildFinal)
        guard case .final(let m) = A.headline(event, host: host(observedAt: nil, now: "2026-10-30T20:13:55Z")).matrix
        else { return XCTFail("a final matrix") }
        XCTAssertEqual(event.heroSettledResult, "away")
        XCTAssertEqual(m.away.result, "Won")
        XCTAssertEqual(m.home.result, "Lost")
        XCTAssertEqual(m.home.finalGoals, .value("3", spoken: "3 goals"))
        XCTAssertEqual(m.away.finalGoals, .value("4", spoken: "4 goals"))
        // 0.655 / 0.345 served with 66 / 34 rendered: the served integers, both or neither.
        XCTAssertEqual(m.home.pregameChance.text, "66%")
        XCTAssertEqual(m.away.pregameChance.text, "34%")
    }

    // MARK: Before

    func testBeforeTheStartTheMatrixPrintsTheHerosPairAndWithholdsTheForecastBothPlatformsRefuse() throws {
        let event = try detail(Self.devilsKnightsBefore)
        let host = host(observedAt: event.heroProbabilityObservedAt, now: "2026-10-30T20:13:55Z")
        XCTAssertEqual(A.phase(event, now: host.now), .before)
        XCTAssertEqual(A.header(event, phase: .before).title, "Vegas Golden Knights vs New Jersey Devils")

        let headline = A.headline(event, host: host)
        let start = try XCTUnwrap(event.commenceTime?.asDate)
        XCTAssertEqual(headline.state, "Before game · \(A.timeWords(start, host: host)) start")
        XCTAssertEqual(headline.stateContext, A.dayWords(start, host: host))
        guard case .before(let m) = headline.matrix else { return XCTFail("a before matrix") }
        XCTAssertEqual(m.chance.title, "Current chance")
        XCTAssertEqual(m.home.chance, .value("51%", spoken: "51 percent"))
        XCTAssertEqual(m.away.chance, .value("49%", spoken: "49 percent"))
        XCTAssertEqual(m.chance.provenance,
                       "Recorded \(A.clockWords(try XCTUnwrap(event.heroProbabilityObservedAt?.asDate), host: host))",
                       "the hero's `blend` source has no served display name here, so it is not named")
        // 3.5 / 2.5 goals from 19 sportsbooks. Native's hero gate alone would print "Proj. 3-4", but the
        // projected-final format table refuses hockey (web's `eventPageProjectedPair` withholds it), so the
        // matrix asks both and withholds — one answer on both platforms. The divergence is the owners' to resolve.
        XCTAssertEqual(EventDetailView.projectionText(event, ladderHome: nil, ladderAway: nil, hasScore: false, now: host.now),
                       "Proj. 3-4", "RECORDED divergence: native's hero gate admits this pair")
        XCTAssertNil(LiveProjectedFinalAdmission2920.format(forSport: event.sport))
        XCTAssertEqual(m.home.projectedGoals, .absent("No pregame forecast"))
        XCTAssertEqual(m.away.projectedGoals, .absent("No pregame forecast"))
        XCTAssertNil(m.projectedGoals.provenance)
    }

    func testAQuoteOlderThanTheLiveStaleWindowOrUndatedIsLastRecordedNeverCurrent() throws {
        let event = try detail(Self.devilsKnightsBefore)
        let observed = try XCTUnwrap(event.heroProbabilityObservedAt?.asDate)
        let late = observed.addingTimeInterval(SourceAge.liveStaleAfter + 60)
        let stale = A.Host(probabilityObservedAt: observed, now: late, calendar: Self.pacific, locale: Locale(identifier: "en_US"))
        let undated = host(observedAt: nil, now: "2026-10-30T20:13:55Z")
        let interrupted = host(observedAt: event.heroProbabilityObservedAt, now: "2026-10-30T20:13:55Z", interrupted: true)
        for host in [stale, undated, interrupted] {
            guard case .before(let m) = A.headline(event, host: host).matrix else { return XCTFail("a before matrix") }
            XCTAssertEqual(m.chance.title, "Last recorded chance")
            XCTAssertEqual(m.home.chance.text, "51%", "the pair is the hero's either way; only its subject changes")
        }
    }

    func testThePhaseIsTheStatusAloneAndAMissingScoreHasItsOwnWords() throws {
        let before = try detail(Self.devilsKnightsBefore)
        // After the listed start but still served `scheduled`: the status decides, not the clock.
        XCTAssertEqual(A.phase(before, now: "2026-10-30T23:30:00Z".asDate!), .before)
        let slots = A.goalSlots(before, host: host(observedAt: nil, now: "2026-10-30T20:13:55Z"), final: false)
        XCTAssertEqual(slots.home, .absent("Score unavailable"))
        XCTAssertEqual(slots.away, .absent("Score unavailable"))
        XCTAssertNil(slots.provenance)
    }

